<?php namespace App\Filament\Resources;use App\Models\AcademicOrder;use App\Filament\Resources\AcademicOrderResource\Pages;use App\Services\PeriodGuard;use Illuminate\Support\Facades\DB;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class AcademicOrderResource extends Resource{protected static ?string $model=AcademicOrder::class;protected static ?string $navigationGroup='Учебная часть';protected static ?string $navigationLabel='Приказы по студентам';protected static ?string $pluralModelLabel='Приказы по студентам';public static function form(Form $f):Form{return $f->schema([Forms\Components\TextInput::make('number')->label('Номер')->required(),Forms\Components\DatePicker::make('order_date')->label('Дата')->required(),Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name)]))->searchable(),Forms\Components\TextInput::make('type')->label('Тип приказа')->required(),Forms\Components\TextInput::make('title')->label('Наименование')->required()->columnSpan('full'),Forms\Components\Textarea::make('basis')->label('Основание')->columnSpan('full')])->columns(2);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('order_date')->label('Дата')->date('d.m.Y')->sortable(),Tables\Columns\TextColumn::make('number')->label('№')->searchable(),Tables\Columns\TextColumn::make('type')->label('Тип')->searchable(),Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($id)=>($s=DB::table('students')->where('id',$id)->first())?trim($s->last_name.' '.$s->first_name):'—'),Tables\Columns\TextColumn::make('title')->label('Наименование')->limit(50)])->actions([Tables\Actions\EditAction::make()]);}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{$q=parent::getEloquentQuery();$p=request()->attributes->get('academic_period');return $p?$q->where('academic_period_id',$p->id):$q;}public static function canViewAny():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->canDo('students.manage'));}public static function canCreate():bool{return static::canViewAny();}public static function canEdit($record):bool{return static::canViewAny();}public static function canDelete($record):bool{return false;}public static function getPages():array{return['index'=>Pages\ListAcademicOrders::route('/'),'create'=>Pages\CreateAcademicOrder::route('/create'),'edit'=>Pages\EditAcademicOrder::route('/{record}/edit')];}}